package cn.bidcheck.verification;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class LayoutEvidenceIndexTest {
    Map<String,Object> cell(String id,String table,int row,int column,int block,String text){Map<String,Object> m=new LinkedHashMap<>();m.put("id",id);m.put("kind","TABLE_CELL");m.put("tableId",table);m.put("row",row);m.put("column",column);m.put("rowSpan",1);m.put("columnSpan",1);m.put("documentBlock",block);m.put("text",text);m.put("documentHash",cn.bidcheck.compat.Java8Api.repeat("a", 64));m.put("documentVersion",2);m.put("source","OOXML_NATIVE");return m;}
    @Test void nativeWordHeaderSourcesRetainTheirOriginalBlocksAndVersion(){java.util.Map<java.lang.String, java.lang.Object> header=cell("header","t",1,1,5,"姓名");java.util.Map<java.lang.String, java.lang.Object> value=cell("value","t",3,1,7,"合成甲");cn.bidcheck.verification.LayoutEvidenceIndex index=new LayoutEvidenceIndex();index.add("d",cn.bidcheck.compat.Java8Api.mapOf("status", "COMPLETE", "documentHash", cn.bidcheck.compat.Java8Api.repeat("a", 64), "spans", cn.bidcheck.compat.Java8Api.listOf(header, value)));java.util.List<java.util.Map<java.lang.String, java.lang.Object>> out=index.apply(cn.bidcheck.compat.Java8Api.mapOf("documentId", "d", "location", 7, "locationType", "BLOCK"));assertEquals(2,out.size());assertEquals(cn.bidcheck.compat.Java8Api.setOf(5, 7),new HashSet<>(cn.bidcheck.compat.Java8Api.toList(out.stream().map(r->r.get("location")))));assertTrue(out.stream().allMatch(r->r.get("locationType").equals("BLOCK")&&r.get("documentVersion").equals(2)));assertTrue(out.stream().noneMatch(r->r.get("locationType").equals("PAGE")));}
    @Test void matchingNumberInDifferentLocationNamespaceDoesNotSelectAWordBlock(){cn.bidcheck.verification.LayoutEvidenceIndex index=new LayoutEvidenceIndex();index.add("d",cn.bidcheck.compat.Java8Api.mapOf("status", "COMPLETE", "spans", cn.bidcheck.compat.Java8Api.listOf(cell("c","t",3,1,7,"甲"))));assertTrue(index.apply(cn.bidcheck.compat.Java8Api.mapOf("documentId", "d", "location", 7, "locationType", "PAGE")).isEmpty());}
    @Test void repeatedIdentifierRetrievesAdjacentHeaderAndDataButNeverSkippedPage(){java.util.ArrayList<java.util.Map<java.lang.String, java.lang.Object>> spans=new ArrayList<Map<String,Object>>();for(int page:cn.bidcheck.compat.Java8Api.listOf(1, 2, 4)){java.util.Map<java.lang.String, java.lang.Object> id=cell("id"+page,"t"+page,3,2,page,"110101199001010011");id.put("physicalPage",page);java.util.Map<java.lang.String, java.lang.Object> header=cell("header"+page,"t"+page,1,2,page,"身份证号码");header.put("physicalPage",page);spans.add(id);spans.add(header);}cn.bidcheck.verification.LayoutEvidenceIndex index=new LayoutEvidenceIndex();index.add("d",cn.bidcheck.compat.Java8Api.mapOf("status", "COMPLETE", "spans", spans));java.util.List<java.util.Map<java.lang.String, java.lang.Object>> out=index.apply(cn.bidcheck.compat.Java8Api.mapOf("documentId", "d", "location", 1, "locationType", "PAGE"));assertEquals(cn.bidcheck.compat.Java8Api.setOf(1, 2),new HashSet<>(cn.bidcheck.compat.Java8Api.toList(out.stream().map(r->r.get("location")))));assertTrue(out.stream().anyMatch(r->r.get("spanId").equals("header2")));}
    @Test void eightyTextboxesAndEarlierRowsCannotStarveTheTargetRowAndRealHeaders(){java.util.ArrayList<java.util.Map<java.lang.String, java.lang.Object>> spans=new ArrayList<Map<String,Object>>();for(int i=0;i<100;i++)spans.add(new LinkedHashMap<>(cn.bidcheck.compat.Java8Api.mapOf("id", "box"+i, "kind", "OCR_TEXT_BOX", "text", "文字框"+i, "physicalPage", 1)));for(int r=1;r<=100;r++)for(int c=1;c<=2;c++){java.util.Map<java.lang.String, java.lang.Object> item=cell("row"+r+"col"+c,"large",r,c,1,r==1?(c==1?"姓名":"缴费月份"):r==99?(c==1?"目标甲":"2025-01、2025-02、2025-03"):"其他"+r+"值"+c);item.put("physicalPage",1);item.put("header",r==1);spans.add(item);}cn.bidcheck.verification.LayoutEvidenceIndex index=new LayoutEvidenceIndex();index.add("d",cn.bidcheck.compat.Java8Api.mapOf("status", "COMPLETE", "spans", spans));java.util.List<java.util.Map<java.lang.String, java.lang.Object>> out=index.apply(cn.bidcheck.compat.Java8Api.mapOf("documentId", "d", "location", 1, "locationType", "PAGE", "subject", "目标甲"));java.util.List<java.lang.Object> ids=cn.bidcheck.compat.Java8Api.toList(out.stream().map(r->r.get("spanId")));assertTrue(ids.containsAll(cn.bidcheck.compat.Java8Api.listOf("row99col1", "row99col2", "row1col1", "row1col2")));assertTrue(out.size()<=120);assertTrue(out.stream().mapToInt(r->r.get("text").toString().length()).sum()<=16000);assertEquals("TABLE_CELL",out.get(0).get("kind"));}
    @Test void currentSourceQuoteCanSelectALateRowWithoutAResolvedPersonQuery(){java.util.ArrayList<java.util.Map<java.lang.String, java.lang.Object>> spans=new ArrayList<Map<String,Object>>();for(int r=1;r<=140;r++){java.util.Map<java.lang.String, java.lang.Object> item=cell("r"+r,"t",r,1,1,r==1?"姓名":r==139?"目标甲":"其他人"+r);item.put("physicalPage",1);item.put("header",r==1);spans.add(item);}cn.bidcheck.verification.LayoutEvidenceIndex index=new LayoutEvidenceIndex();index.add("d",cn.bidcheck.compat.Java8Api.mapOf("status", "COMPLETE", "spans", spans));java.util.List<java.util.Map<java.lang.String, java.lang.Object>> out=index.apply(cn.bidcheck.compat.Java8Api.mapOf("documentId", "d", "location", 1, "locationType", "PAGE", "sourceQuote", "姓名：目标甲 本月已缴纳"));assertTrue(out.stream().anyMatch(r->"r139".equals(r.get("spanId"))));}
}
